import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    student_scores = defaultdict(list)

    idx = 1
    for _ in range(n):
        name = data[idx]
        score = int(data[idx + 1])
        student_scores[name].append(score)
        idx += 2

    avg_scores = {}
    for name, scores in student_scores.items():
        avg = sum(scores) / len(scores)
        avg_scores[name] = avg

    sorted_students = sorted(avg_scores.keys(), key=lambda x: (-avg_scores[x], x))

    print("Sorted List:")
    for name in sorted_students:
        print(f"{name} {avg_scores[name]:.2f}")

    if sorted_students:
        print(f"Top Scorer: {sorted_students[0]}")

if __name__ == "__main__":
    main()
